__NUXT_JSONP__("/posts/todo-vue-js-app-wip1-new-project-startup", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H){return {data:[{post:{slug:r,description:p,title:"Todo vue.js app WIP#1 : new project startup",type:f,imgCover:r,tags:[s,t,f],createdAt:"2019-01-31T00:00:00.000Z",toc:[{id:u,depth:g,text:v},{id:w,depth:g,text:x},{id:y,depth:g,text:z},{id:A,depth:g,text:B},{id:q,depth:g,text:C}],body:{type:D,children:[{type:b,tag:e,props:{},children:[{type:a,value:p}]},{type:a,value:c},{type:a,value:c},{type:b,tag:"ol",props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:o,props:{to:E},children:[{type:a,value:"Part 1"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:o,props:{to:"\u002Fposts\u002Ftodo-vue-js-app-wip2-vuex-modules-firebase"},children:[{type:a,value:"Part 2"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:o,props:{to:"\u002Fposts\u002Ftodo-vue-js-app-wip3-turning-spa-pwa"},children:[{type:a,value:"Part 3"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:o,props:{to:"\u002Fposts\u002Ftodo-vue-js-app-wip4-alpha-launch-weekx"},children:[{type:a,value:"Part 4"}]}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:h,props:{id:u},children:[{type:b,tag:i,props:{href:"#diving-into-vuejs",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Now I finished the whole Vueschool.io masterclass early in january, there was no time to loose before using this new acquired knowledge. A friend of mine has been thinking about building a small app as an excellent opportunity to start using a new framework. It's a kind of an advanced to-do list (not the most original idea), but focused on the personal development side. Anyway, I decided to pick up the idea and shape it to myself, so that I could really use it on a daily basis."}]},{type:a,value:c},{type:b,tag:h,props:{id:w},children:[{type:b,tag:i,props:{href:"#thinking-the-stack-ahead",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:x}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Before any dev work, I had to think what tools would I need to achieve the whole thing. I ended with this preliminary list :"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Vue.js + CLI scaffold"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Vuex (to centralize data in a store)"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Vuetify.js development framework (to get pre-packaged UI components)"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Firebase (as main backend for persistent datas and user authentication)"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Gulp (for additional builds such as icon font, image compression & retina support..)"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Github + Netlify (for versioning + easy deployment)"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:h,props:{id:y},children:[{type:b,tag:i,props:{href:"#design-process",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"It all starts with a Trello, as it's not only a solo project. This project management tool (that I used to know for years), it still very useful to get a quick overview of what remains to do and how things progress. Then it's time to really think about what the project will look like, which features.. I brainstormed multiple times to get the global picture mentally, then I sketched it, and wireframed it through Sketch as usual."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"This time, I always referenced to the Vuetify.js doc, so that I would easily use their component's library at most. After that, I quickly deployed these screens on Invision to have a sense of the flow using the app. Finally, I designed the final UI, still with Sketch."}]},{type:a,value:c},{type:b,tag:h,props:{id:A},children:[{type:b,tag:i,props:{href:"#development",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"As much as I could have learned from vueschool.io, it's still when you start your own stuff that the real learning starts. How will I structure my app ? How to think it as components ? Actually I processed step by step with building what I needed first, then it gradually became more complex as I had to do a lot of code refactoring. Of course I did many back and forth with multiple docs and school projects to compare how things are built and get inspirations."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So far, I didn't get stuck and already succeed to build a first working basic prototype. I struggle a bit with Vuex (avoid data mutation directly from components) and Vuetify.js as it added a complexity layer for a first project."}]},{type:a,value:c},{type:b,tag:h,props:{id:q},children:[{type:b,tag:i,props:{href:"#next",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:C}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"It's been a few weeks I started working on it and the worst has yet to come (add Firebase and deal with asynchronous fetchs, deal with periodicities of tasks with time libs, market the app, think about monetization, package for appstores, make the app progressive with caching datas..). Nevertheless, I'm confident I should get by ok with all these obstacles by progressing step by step without rushing too much. As I did with the short 3D film last year, I will use this blog as a personal journal of this app development until it's done."}]}]},excerpt:{type:D,children:[{type:b,tag:e,props:{},children:[{type:a,value:p}]}]},dir:"\u002Fposts",path:E,extension:".md",updatedAt:"2025-10-10T15:29:17.529Z"},relatedPosts:[{title:"Framer & Framer-motion: prototyping workflows",type:f,imgCover:"framer-and-framer-motion-prototyping-workflows.jpg",tags:["framer",q,"framer-motion","Tailwind","Sketch",F,G,f],createdAt:"2022-02-27T00:00:00.000Z",path:"\u002Fposts\u002Fframer-and-framer-motion-prototyping-workflows"},{title:"When Figma takes over Sketch",type:f,imgCover:"when-figma-takes-over-sketch.jpg",tags:["figma",t,F,f],createdAt:"2022-08-31T00:00:00.000Z",path:"\u002Fposts\u002Fwhen-figma-takes-over-sketch"},{title:"Weekx progressive web app",type:H,imgCover:"weekx-progressive-web-app",tags:[s,"vuex","pwa",G,H],createdAt:"2019-03-19T00:00:00.000Z",path:"\u002Fposts\u002Fweekx-progressive-web-app"},{title:"Nuxt.js puzzle game development - WIP#1",type:f,imgCover:"nuxt-js-puzzle-game-development-wip1",tags:["nuxt","cordova","games",f],createdAt:"2019-06-07T00:00:00.000Z",path:"\u002Fposts\u002Fnuxt-js-puzzle-game-development-wip1"}]}],fetch:[{counter:13},{counter:7},{counter:72}],mutations:[]}}("text","element","\n","li","p","article",2,"h2","a","true",-1,"span","icon","icon-link","nuxt-link","This post is part of a full walkthrough of building todo app using vue.js","next","todo-vue-js-app-wip1-new-project-startup","vue","sketch","diving-into-vuejs","Diving into vue.js","thinking-the-stack-ahead","Thinking the stack ahead","design-process","Design process","development","Development","Next","root","\u002Fposts\u002Ftodo-vue-js-app-wip1-new-project-startup","miscs","devs","design")));